INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:فجر:ibn_manzur_lisan_arab', 'فجر', '0680f94e5285274750c31fb94f', 'فالفَجْرُ أَصله الشَّقُّ، وَمِنْهُ أُخِذَ فَجْرُ السِّكْرِ، وَهُوَ بَثْقُه', 'at bottom it is splitting, as breaching a dam', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_c87959c4b636c573', '2629', 5, 'blk_lsn_58ed4bb636405b06', 0, NULL, 'Marker: «أصله». Reading: splitting. Quoted from al-Azharī via Lisān.', 'high', 'active');
